const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length < 2) return;

    const n = parseInt(input[0], 10);
    const s = input[1];

    let maxLen = 1;

    for (let i = 0; i < n; i++) {
        // Palíndromos de comprimento ímpar com centro em i
        let l = i;
        let r = i;
        while (l >= 0 && r < n && s[l] === s[r]) {
            const currentLen = r - l + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            l--;
            r++;
        }

        // Palíndromos de comprimento par com centro entre i e i + 1
        l = i;
        r = i + 1;
        while (l >= 0 && r < n && s[l] === s[r]) {
            const currentLen = r - l + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            l--;
            r++;
        }
    }

    console.log(maxLen);
}

main();
